import{_ as t,o as r,c as s,ah as a}from"./chunks/framework.C-FRNfAJ.js";const g=JSON.parse('{"title":"Formateur Principal","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/equipe/formateur.md","filePath":"src/guide/equipe/formateur.md"}'),o={name:"guide/equipe/formateur.md"};function n(u,e,i,l,d,c){return r(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="formateur-principal" tabindex="-1">Formateur Principal <a class="header-anchor" href="#formateur-principal" aria-label="Permalink to &quot;Formateur Principal&quot;">​</a></h1><p>Le Formateur Principal enseigne et note dans <strong>Sève</strong>, et tient dans <strong>Kura</strong> ce qui touche à ses cohortes : présence en présentiel, rattrapages, suivi de la rémunération. Le rôle est attribué par le Coordinateur pédagogique.</p><h2 id="vos-cohortes" tabindex="-1">Vos cohortes <a class="header-anchor" href="#vos-cohortes" aria-label="Permalink to &quot;Vos cohortes&quot;">​</a></h2><p><strong>Formation → Cohortes</strong> ne liste que <strong>les cohortes auxquelles vous êtes affecté</strong>. Ouvrir une cohorte d&#39;un autre formateur est refusé. Chaque fiche montre ses dates, son effectif, ses apprenants avec leur format et leur statut, et les documents de la cohorte (voir plus bas).</p><p>Dans la liste des apprenants, un repère <strong>« Pas de droit à l&#39;image »</strong> signale ceux qui l&#39;ont refusé : ne diffusez aucun enregistrement où ils apparaissent.</p><p>Vous ne pouvez pas créer, confirmer, reporter ni annuler une cohorte : c&#39;est l&#39;affaire du Coordinateur. Vous n&#39;avez pas non plus accès à la banque de questions du test d&#39;admission.</p><h2 id="la-presence" tabindex="-1">La présence <a class="header-anchor" href="#la-presence" aria-label="Permalink to &quot;La présence&quot;">​</a></h2><p>Depuis la fiche de la cohorte, <strong>Présence</strong> donne, pour chaque apprenant, le taux d&#39;absence (heures manquées sur le volume horaire de la formation) avec un repère au seuil de 30 %, et la liste des séances.</p><ul><li>Les <strong>classes virtuelles</strong> sont relues depuis Sève chaque heure. Elles apparaissent ici sans que vous ayez rien à saisir, et ne se modifient pas dans Kura. Pour cela, le Coordinateur doit avoir renseigné l&#39;identifiant du cours Sève de la cohorte.</li><li>Les <strong>séances en présentiel</strong>, vous les saisissez : <strong>Saisir une séance</strong>, avec la date et l&#39;heure, la durée en minutes et un intitulé facultatif.</li></ul><p>La saisie n&#39;est possible qu&#39;<strong>une fois la cohorte démarrée</strong>, et la séance doit avoir eu lieu. Chaque apprenant en présentiel ou en hybride est <strong>présent par défaut</strong> : décochez ceux qui sont absents ou notez-les en retard ou absents. Un retard compte comme une présence, une absence excusée comme une absence.</p><p>Vous pouvez <strong>corriger</strong> ou <strong>supprimer</strong> une séance en présentiel ; les taux se recalculent, et tout est journalisé. Quand le taux d&#39;un apprenant dépasse 30 %, il est prévenu ainsi que l&#39;équipe pédagogique, une seule fois. Une correction qui le ramène sous le seuil réarme l&#39;alerte.</p><h2 id="les-notes-dans-seve" tabindex="-1">Les notes dans Sève <a class="header-anchor" href="#les-notes-dans-seve" aria-label="Permalink to &quot;Les notes dans Sève&quot;">​</a></h2><p>Vous notez chaque <strong>bloc de compétences</strong> dans le carnet de notes du cours Sève, sur 20. Pour que Kura retrouve la note, l&#39;élément de notation porte le code du bloc comme <strong>numéro d&#39;identification</strong> : <code>KURA-BLOC-{id}</code>. Les codes de tous les blocs sont listés sur la page <strong>Résultats</strong> de la cohorte.</p><p>Les notes remontent dans Kura chaque heure. Une nouvelle note sur un bloc déjà noté <strong>corrige</strong> la tentative en cours.</p><h2 id="les-resultats-et-les-rattrapages" tabindex="-1">Les résultats et les rattrapages <a class="header-anchor" href="#les-resultats-et-les-rattrapages" aria-label="Permalink to &quot;Les résultats et les rattrapages&quot;">​</a></h2><p>La page <strong>Résultats</strong> de la cohorte montre, pour chaque apprenant, ses notes par bloc, sa moyenne (pondérée par la durée des blocs) et la décision du jury. Un bloc est :</p><table tabindex="0"><thead><tr><th>Note</th><th>Lecture</th></tr></thead><tbody><tr><td>10/20 et plus</td><td>Validé</td></tr><tr><td>De 8 à moins de 10</td><td>Compensable : rattrapé par la moyenne</td></tr><tr><td>Moins de 8</td><td>Éliminatoire</td></tr></tbody></table><p>Vous pouvez <strong>ouvrir un rattrapage</strong> pour un bloc sous 10/20, <strong>15 jours au moins</strong> après la dernière note du bloc, dans la limite de <strong>2 rattrapages</strong> (3 tentatives au total). La page indique la date à partir de laquelle il est possible.</p><p>Un rattrapage ouvert <strong>attend la première note donnée dans Sève après son ouverture</strong> et se remplit tout seul. Vous pouvez l&#39;annuler tant qu&#39;il n&#39;est pas noté.</p><p>Les décisions du <strong>jury</strong> (projet tutoré, soutenance, stage) sont saisies par le Coordinateur. La délivrance du certificat lui revient aussi.</p><h2 id="les-documents-de-la-cohorte" tabindex="-1">Les documents de la cohorte <a class="header-anchor" href="#les-documents-de-la-cohorte" aria-label="Permalink to &quot;Les documents de la cohorte&quot;">​</a></h2><p>Depuis la fiche de la cohorte, vous téléchargez, générés à la demande :</p><ul><li>le <strong>calendrier prévisionnel</strong> : blocs, dates clés, échéances de paiement, jours de jury, jours fériés ;</li><li>le <strong>procès-verbal de soutenance</strong>, une fois produit par le Coordinateur.</li></ul><p>Le rapport d&#39;activité (places, présence, résultats) reste réservé au Coordinateur et à l&#39;Administrateur.</p><h2 id="votre-remuneration" tabindex="-1">Votre rémunération <a class="header-anchor" href="#votre-remuneration" aria-label="Permalink to &quot;Votre rémunération&quot;">​</a></h2><p><strong>Finance → Ma rémunération</strong> montre vos lignes <strong>cohorte par cohorte</strong> et les versements reçus, avec trois totaux : en attente de validation, validé à verser, versé.</p><p>Kura calcule votre rémunération <strong>à la fin de la cohorte</strong>, selon les taux en vigueur à son démarrage. Le Coordinateur l&#39;ajuste si besoin et la valide ; le versement se fait hors de Kura et il l&#39;enregistre. Si vous êtes plusieurs formateurs sur une cohorte, votre part est partagée à parts égales.</p>',27)])])}const h=t(o,[["render",n]]);export{g as __pageData,h as default};
